corrected_code:
router.param('id', async (req, res, next, id) => {
  const item = await Profile.findById(id);
  if (!item || item.ownerId !== req.user.id) return res.status(403).send('Forbidden');
  req.item = item;
  next();
});
router.post('/profile/:id/process', (req, res) => {
  req.item.process();
  res.send('Processed');
});
